// vec returns the bytes of a known answer.
func vec(t testing.TB, name string) []byte {
	t.Helper()
	for line := range strings.SplitSeq(vectorText, "\n") {
		n, h, ok := strings.Cut(line, " ")
		if ok && n == name {
			b, err := hex.DecodeString(h)
			if err != nil {
				t.Fatalf("vector %s: %v", name, err)
			}
			return b
		}
	}
	t.Fatalf("no vector %s", name)
	return nil
}

// pat returns n bytes seed, seed+1, ... the input pattern of the known answers.
func pat(n int, seed byte) []byte {
	b := make([]byte, n)
	for i := range b {
		b[i] = seed + byte(i)
	}
	return b
}

func arr(b []byte) (a [32]byte) {
	copy(a[:], b)
	return a
}
